if (size <= 0) return nullptr;

std::priority_queue<TreeNode*, std::vector<TreeNode*>, std::greater<TreeNode*>> pq;

for (int i = 0; i < size; ++i) {
    TreeNode* node = new TreeNode(values[i], freqs[i]);
    pq.push(node);
}

while (pq.size() > 1) {
    TreeNode* left = pq.top();
    pq.pop();
    TreeNode* right = pq.top();
    pq.pop();

    TreeNode* parent = new TreeNode('\0', left->freq + right->freq);
    parent->left = left;
    parent->right = right;
    pq.push(parent);
}

return pq.top();

